local function set(group, highlight)
    vim.api.nvim_set_hl(0, group, highlight)
end

local function clear_background(group)
    local ok, highlight = pcall(vim.api.nvim_get_hl, 0, { name = group, link = false })
    if not ok then
        highlight = {}
    end
    highlight.bg = nil
    highlight.ctermbg = nil
    vim.api.nvim_set_hl(0, group, highlight)
end

local function apply_semantic_tokens()
    for semantic_name, color in pairs(M.semantic) do
        local parts = vim.split(semantic_name, ".", { plain = true })
        local token_type = table.remove(parts, 1)
        if #parts == 0 then
            set("@lsp.type." .. token_type, { fg = color })
        else
            for _, modifier in ipairs(parts) do
                set("@lsp.typemod." .. token_type .. "." .. modifier, { fg = color })
            end
        end
    end
end

